UPDATE characters SET data = json_remove(json_set(data, '$.jinxes', json('[{"name":"Banshee","align":"good","text":"If the Abysewhell is in play & the Banshee dies from an evil player answering their question correctly, their ability activates immediately.","id":"banshee"},{"name":"Butler","align":"good","text":"The Butler''s ability is replaced with \"Each night, choose a living player (not yourself): you become their alignment (you don''t know which.)\"","id":"butler"},{"name":"Cannibal","align":"good","text":"The Cannibal instead gains the ability of the most recent player to die to a good player answering their question correctly.","id":"cannibal"},{"name":"Devil''s Advocate","align":"evil","text":"Devil''s Advocate-protected-players cannot die by answering their question incorrectly.","id":"devilsadvocate"},{"name":"Engineer","align":"good","text":"The Engineer cannot swap out the Abysewhell.","id":"engineer"},{"name":"Evil Twin","align":"evil","text":"Only 1 jinxed character can be in play.","id":"eviltwin"},{"name":"Farmer","align":"good","text":"If the Abysewhell is in play & the Farmer dies from an evil player answering their question correctly, a good player becomes a Farmer that night.","id":"farmer"},{"name":"Fearmonger","align":"evil","text":"Only 1 jinxed character can be in play.","id":"fearmonger"},{"name":"Flowergirl","align":"good","text":"The Flower Girl instead learns if a Demon or Minion correctly answered any questions for their ability.","id":"flowergirl"},{"name":"Fortune Teller","align":"good","text":"Minions register as the Demon to the Fortune Teller.","id":"fortuneteller"},{"name":"Goblin","align":"evil","text":"If the Abysewhell is in play & the Goblin dies from a good player answering their question correctly (whilst they claimed to be the Goblin), their team wins.","id":"goblin"},{"name":"Innkeeper","align":"good","text":"Innkeeper-protected-players cannot die from players answering their question correctly.","id":"innkeeper"},{"name":"Mastermind","align":"evil","text":"The Mastermind''s ability is replaced with \"The first 2 times you answer incorrectly per day, you don''t die.\".","id":"mastermind"},{"name":"Mayor","align":"good","text":"If the Abysewhell is in play & the Mayor is one of the last two good players alive, the next two times they would''ve died, they don''t.","id":"mayor"},{"name":"Minstrel","align":"good","text":"If a Minion dies during the day, the Minstrel''s ability activates starting dusk and lasts until dusk tommorow.","id":"minstrel"},{"name":"Monk","align":"good","text":"Monk-protected-players cannot die from evil players answering their question correctly.","id":"monk"},{"name":"Pacifist","align":"good","text":"If the Pacifist is in-play, good players might not die by answering their question incorrectly.","id":"pacifist"},{"name":"Ravenkeeper","align":"good","text":"If the Abysewhell is in play & the Ravenkeeper dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","id":"ravenkeeper"},{"name":"Sage","align":"good","text":"If the Abysewhell is in play & the Sage dies during the day by an player answering their question correctly, they wake that night to learn 2 evil players. They are drunk if their killer is good.","id":"sage"},{"name":"Saint","align":"good","text":"If the Abysewhell is in play & the Saint dies during the day by a good player answering their question correctly, their team loses.","id":"saint"},{"name":"Scarlet Woman","align":"evil","text":"If the Scarlet Woman is in-play, the first time the Abysewhell answers their question incorrectly, they are instead declared correct.","id":"scarletwoman"},{"name":"Soldier","align":"good","text":"The Soldier cannot die from evil players answering their question correctly.","id":"soldier"},{"name":"Town Crier","align":"good","text":"The Town Crier instead learns how many Minions answered any questions for their ability. If the number would be 0, they are instead drunk that night.","id":"towncrier"},{"name":"Undertaker","align":"good","text":"The Undertaker instead learns the last player to die today to a good player answering their question correctly.","id":"undertaker"},{"name":"Virgin","align":"good","text":"The first time the Virgin would die from a player answering their question correctly, if the killer is a Townsfolk, they are executed immediately.","id":"virgin"},{"name":"Vizier","align":"evil","text":"The Vizier''s ability is replaced with \"You cannot die during the day. You may suggest a question to the Storyteller they''ll use. You are not required to die for evil to lose.\".","id":"vizier"},{"name":"Witch","align":"evil","text":"Witch-cursed players die after answering their question, even if correct.","id":"witch"},{"name":"Zealot","align":"good","text":"Only 1 jinxed character can be in play.","id":"zealot"},{"name":"Bloodnote","align":"good","text":"After a player answers a question correctly, they still die, regardless of the { } text.","id":"bloodnote_scp_fragmented_veil"},{"name":"Pipe Maze","align":"evil","text":"If a player would die during the day except by answering a question incorrectly, it follows the Pipemaze''s rule.","slug":"pipe-maze"},{"name":"Sauelsuesor","align":"good","text":"Players killed by the Sauelsuesor answering their question correctly register as nominated by them.","slug":"sauelsuesor"},{"name":"Tunisian","align":"good","text":"The Tunisian-protected-good-players cannot die from players answering their question correctly.","slug":"tunisian"},{"name":"Peacemonger","align":"good","text":"If no good player answers a question correctly during the day, the Peacemonger''s ability will activate.","slug":"peacemonger-scp-fragmented-veil"},{"name":"Immaterial","align":"good","text":"If the Immaterial would die during the day, they might live and kill a teammate tonight.","slug":"immaterial"},{"name":"Revenant","align":"good","text":"If the Abysewhell is in play & the Revenant dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","slug":"revenant-scp-fragmented-veil"},{"name":"GOC Physics","align":"good","text":"GOC Physics cannot die from evil players answering their question correctly whilst they activated their ability last night.","slug":"goc-physics"},{"name":"Autarch","align":"evil","text":"Players who answer a question, whether they are right or wrong, register as having nominated to the Autarch.","id":"autarch_hblreleased"},{"name":"Crawler","align":"evil","text":"Only 1 jinxed character can be in play.","id":"crawler_hblreleased"},{"name":"Chupacabra","align":"evil","text":"If the Abysewhell is in play, the Chupacabra can only choose to kill players that killed evil players today by answering correctly today.","id":"chupacabra_hblreleased"},{"name":"Fetch","align":"good","text":"The 1st player who dies during the day registers as executed to the Fetch.","id":"fetch_hblreleased"},{"name":"Haberdasher","align":"good","text":"Only 1 jinxed character can be in play.","id":"haberdasher_hblreleased"},{"name":"Moonflower","align":"good","text":"Players who die by a good player answering their question correctly register as executed to the Moonflower.","id":"moonflower_hblreleased"},{"name":"Porcher","align":"good","text":"Only 1 jinxed character can be in play.","id":"porcher_hblreleased"},{"name":"Rancher","align":"good","text":"Evil players that die to a good player answering their question correctly register as executed to the Rancher.","id":"rancher_hblreleased"},{"name":"Seraph","align":"good","text":"Good players who die by the Seraph answering their question correctly register as executed to the Seraph.","id":"seraph_hblreleased"},{"name":"Vampire","align":"evil","text":"If the Abysewhell is in play & an evil player would kill another evil player by answering their question correctly, the victim lives. If a Townsfolk chooses to kill the Vampire by answering their question correctly, both players are poisoned until dawn, even if the Vampire dies.","id":"vampire_hblreleased"},{"name":"Wig Snatcher","align":"good","text":"Players who die by a evil player answering their question correctly register as dieing at night to the Wig Snatcher.","id":"wigsnatcher_hblreleased"},{"name":"Archivist","align":"good","text":"Each day, the Archivist may ask a yes/no question about a question that a player received. This answer is arbitrary is that player is not evil.","id":"archivist_the_bootleggers_anthology"},{"name":"Cardinal","align":"good","text":"If the Abysewhell is in play, & the Cardinal is chosen by a player answering their question correctly, their alignment becomes opposite to whoever chose them, even as they die.","id":"cardinal_the_bootleggers_anthology"},{"name":"Deserter","align":"good","text":"Only 1 jinxed character can be in play.","id":"deserter_the_bootleggers_anthology"},{"name":"Fencer","align":"good","text":"The Fencer''s ability is replaced with ''Once per game, during the day, visit the Storyteller to learn the answer to a future question.''","id":"fencer_the_bootleggers_anthology"},{"name":"Firebrand","align":"good","text":"If the Abysewhell is in play & the Firebrand draws first blood (killing another player by answering correctly) and survives, they''ll use their ability tonight.","id":"firebrand_the_bootleggers_anthology"},{"name":"Local Hero","align":"good","text":"If the Abysewhell is in play & an evil player kills the Local Hero by answering their question correctly, the character they know dies tonight.","id":"localhero_the_bootleggers_anthology"},{"name":"Penitent","align":"good","text":"If the Abysewhell is in play & the Penitent dies and the Abysewhell chooses to change their ability whilst dead, a living Minion gets it instead and becomes \"the Demon\".","id":"penitent_the_bootleggers_anthology"},{"name":"Spice Trader","align":"good","text":"Players that answer questions register as voting to the Spice Trader.","id":"spicetrader_the_bootleggers_anthology"},{"name":"Steeplejack","align":"good","text":"If the Abysewhell is in play & the Steeplejack dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","id":"steeplejack_the_bootleggers_anthology"},{"name":"Silversmith","align":"good","text":"If the Abysewhell is in play & only 3 players live on the final day, the Silversmith may suggest a question to the Storyteller they''ll use.","id":"silversmith_the_bootleggers_anthology"},{"name":"Warden","align":"evil","text":"If the Abysewhell is in play & an evil player would kill the player the Warden chose by answering their question correctly, that player does not die.","id":"warden_the_bootleggers_anthology"},{"name":"Wight","align":"evil","text":"The Wight & ''cursed'' players ''curse'' whoever kills it by answering their question correctly, up to 2 people. Cursed Townsfolk are poisoned.","id":"wight_the_bootleggers_anthology"},{"name":"Carpenter","align":"evil","text":"The Carpenter instead learns how many alive neighbours of evil players died today.","id":"carpenter_circus_music"},{"name":"Cleric","align":"good","text":"If the Abysewhell is in play & the Cleric kills an evil player by answering their question whilst they have their ability, good wins.","id":"cleric_circus_music"},{"name":"Kenku","align":"good","text":"If the Abysewhell is in play & a Kenku-protected-players would die from an evil player answering their question correctly, 2 other good players die instead.","id":"kenku_circus_music"},{"name":"Shade","align":"good","text":"If the Abysewhell is in play & the Shade answers a question, right or wrong, their might ability activate on the most recent good winner.","id":"shade_circus_music"},{"name":"Bug Keeper","align":"evil","text":"Players who choose the Bug Keeper by answering correctly register as having nominated them.","id":"bugkeeper_festival_of_lanterns"},{"name":"Firewatcher","align":"good","text":"If a Firewatcher-protected-player would die from an evil player answering their question correctly, they die instead & the day ends.","id":"firewatcher_festival_of_lanterns"},{"name":"Vixin","align":"good","text":"If the Abysewhell is in play & the Vixin dies to a good player answering their question correctly, their ability activates tonight.","id":"vixin_festival_of_lanterns"},{"name":"Junkbug","align":"good","text":"If the Junkbug correctly answers a question & chooses to kill an evil player, their ability activates to drunken a player.","id":"junkbug_stardustcollectionreleased"},{"name":"Trapsmith","align":"good","text":"If an evil player kills the Trapsmith-protected player by answering their question correctly, they are told to pick again.","id":"trapsmith_mistfitsprerelease"},{"name":"Buggane","align":"evil","text":"Only 1 jinxed character can be in play.","id":"buggane_2tfafullcharacterlist"},{"name":"Carpenter","align":"evil","text":"If a good player kills the Carpenter by answering their question correctly, they become a not-in-play evil Minion tonight.","id":"carpenter_2tfafullcharacterlist"},{"name":"Escape Artist","align":"good","text":"The Escape Artist''s ability is replaced with \"If chosen by an player answering their question correctly, before you die, you may publicly ask for a question. If correct & they oppose them, they also die.\".","id":"escapeartist_2tfafullcharacterlist"},{"name":"Lemming","align":"good","text":"If the Abysewhell is in play & the Lemming is chosen by a good player answering their ability, they become a Lemming and not all Lemmings die to their ability.","id":"lemming_2tfafullcharacterlist"},{"name":"Milkmaid","align":"good","text":"If the Abysewhell is in play & the Milkmaid dies during the day by a player answering their question correctly, they wake that night to use their ability. They are drunk if their killer is good.","id":"milkmaid_2tfafullcharacterlist"},{"name":"Rat-Catcher","align":"good","text":"If the Abysewhell is in play & the Rat-Catcher dies during the day by an player answering their question correctly, an alive evil player gains the ability \"Good wins if just 3 players live. The Demon knows who you are\". They are drunk if their killer is good.","id":"ratcatcher_2tfafullcharacterlist"},{"name":"Schemester","align":"good","text":"Only 1 jinxed character can be in play.","id":"schemester_2tfafullcharacterlist"},{"name":"Scorpion","align":"evil","text":"Players that die to a good player answering their question correctly register as executed to the Scorpion.","id":"scorpion_2tfafullcharacterlist"},{"name":"Troll","align":"good","text":"If the Abysewhell is in play & an evil player kills the Troll by answering their question correctly, an evil player dies instead (unless the Troll is drunk).","id":"troll_2tfafullcharacterlist"},{"name":"Vicar","align":"good","text":"Vicar-protected-players cannot die from evil players answering their question correctly.","id":"vicar_2tfafullcharacterlist"},{"name":"White Elephant","align":"good","text":"If the Abysewhell is in play & the White Elephants dies to a good player answering their question correctly, they register as executed.","id":"whiteelephant_2tfafullcharacterlist"},{"name":"Akiryo","align":"evil","text":"Good players who die by another good player answering their question correctly register as executed to the Akiryo.","id":"akiryo_darkartists_stuff"},{"name":"Anthropologist","align":"good","text":"If both the Abysewhell & Anthropologist are in play & no one claimed their character before the day ended, evil wins tonight.","id":"anthropologist_darkartists_stuff"},{"name":"Baker","align":"good","text":"Baker-protected-players cannot die from evil players answering their question correctly.","id":"baker_darkartists_stuff"},{"name":"Bloodless","align":"evil","text":"Only 1 jinxed character can be in play.","id":"bloodless_darkartists_stuff"},{"name":"Bog Dweller","align":"good","text":"If the Abysewhell is in play & the Bogdweller is chosen by a player answering their question correctly, their ability activates tonight.","id":"bogdweller_darkartists_stuff"},{"name":"Breathsnatch","align":"evil","text":"Evil players that die to a good player answering their question correctly register as executed to the Breathsnatch.","id":"breathsnatch_darkartists_stuff"},{"name":"Child of Lir","align":"good","text":"Only 1 jinxed character can be in play.","id":"childoflir_darkartists_stuff"},{"name":"Dockworker","align":"good","text":"If the Abysewhell is in play & an evil player would be killed by a player answering their question correctly, they register as an executed Demon to the Dockworker.","id":"dockworker_darkartists_stuff"},{"name":"Guilt","align":"evil","text":"Players who kill other players by answering their question correctly register as having nominated & executed to the Guilt.","id":"guilt_darkartists_stuff"},{"name":"Haunt","align":"evil","text":"If the Abysewhell is in play & the Haunt or their victim are killed by a good player answering their question correctly, all players learn this.","id":"haunt_darkartists_stuff"},{"name":"Heir","align":"evil","text":"Only 1 jinxed character can be in play.","id":"heir_darkartists_stuff"},{"name":"Houndmaster","align":"good","text":"If the Abysewhell is in play & the Houndmaster choose an evil player when answering their question correctly, their ability activates tonight.","id":"houndmaster_darkartists_stuff"},{"name":"Justice","align":"evil","text":"Only 1 jinxed character can be in play.","id":"justice_darkartists_stuff"},{"name":"Maskbearer","align":"good","text":"Maskbearer-protected-players cannot die from players answering their question correctly.","id":"maskbearer_darkartists_stuff"},{"name":"Moonshiner","align":"good","text":"If the Abysewhell is in play & the Moonshiner is chosen by a player answering their question correctly, they are drunk until dawn, even if the Moonshiner dies.","id":"moonshiner_darkartists_stuff"},{"name":"Mourner","align":"good","text":"Players killed by a player answering their question correctly register as executed to the Mourner.","id":"mourner_darkartists_stuff"},{"name":"Wayfarer","align":"good","text":"If the Abysewhell is in play, the Wayfarer instead learns if the chosen player has killed an evil player by answering their question correctly.","id":"wayfarer_darkartists_stuff"}]')), '$.customBoxes'), updated_at = datetime('now') WHERE slug = 'abysewhell';
